    return np.flatnonzero(~valid), np.flatnonzero(valid)

def reservoir(stream, capacity, draw):
    if capacity == 0:
        return []
    sample = []
    for index, item in enumerate(stream):
        if index < capacity:
            sample.append(item)
        else:
            slot = draw(index+1)
            if slot < capacity:
                sample[slot] = item
    return sample

def merge_pair(tokens, pair, merged_id):
    output = []
    i = 0
    while i < len(tokens):
        if i+1 < len(tokens) and (tokens[i],tokens[i+1]) == tuple(pair):
            output.append(merged_id)
            i += 2
        else:
            output.append(tokens[i])
            i += 1
    return output

def unigram_nll(counts, sequence, alpha, vocabulary_size):
    from math import log
    if not sequence:
        return 0.
    denominator = sum(counts.values()) + alpha*vocabulary_size
    return sum(log(denominator) - log(counts.get(token,0)+alpha) for token in sequence) / len(sequence)

def hysteresis(scores, low, high):
    active = False
    output = []
    for score in scores:
        if score >= high:
            active = True
        elif score <= low:
            active = False
        output.append(active)
    return output

